B.QK=new A.e5("line","Line follower","Line follower","Robotics","Intermediate","Follow a dark line with the IR line sensor.","Follow a line with IR sensors","RoboCore V2",'// Line follower\n// Steers toward the line using the IR line sensor.\n#include <RoboCoreMotors.h>\n#include <RoboCoreSensors.h>\n\nRoboCoreMotors motors;\nLineSensor line;\n\nconst int BASE_SPEED = 45;\nconst float GAIN = 30.0;\n\nvoid setup() {\n  Serial.begin(115200);\n  motors.begin();\n  line.begin();\n}\n\nvoid loop() {\n  // line.read() returns -1.0 (line far left) to 1.0 (far right)\n  float pos = line.read();\n  int turn = pos * GAIN;\n  motors.drive(BASE_SPEED + turn, BASE_SPEED - turn);\n  Serial.print("line=");\n  Serial.println(pos, 2);\n  delay(50);\n}\n',null,B.Yr,"LineFollower",null,null)
B.QI=new A.e5("servo","Servo sweep","Servo sweep","Robotics","Beginner","Sweep a servo from 0\xb0 to 180\xb0 and back.","Hobby servo on PWM","V2 \xb7 ESP32 boards",'// Servo sweep\n// Sweeps a servo on pin 18 from 0 to 180 degrees and back.\n#include <ESP32Servo.h>\n\nServo arm;\n\nvoid setup() {\n  Serial.begin(115200);\n  arm.attach(18);\n}\n\nvoid loop() {\n  for (int angle = 0; angle <= 180; angle += 10) {\n    arm.write(angle);\n    delay(60);\n  }\n  for (int angle = 180; angle >= 0; angle -= 10) {\n    arm.write(angle);\n    delay(60);\n  }\n  Serial.println("sweep done");\n}\n',null,null,"ServoSweep",null,null)
